/* Steps angle a toward b by at most c, with wraparound. */
float step_rotation_toward_target(float a, float b, float c) {
    float r = FastSubRots(b, a);
    if (!(r > 0.0f)) {
        c = -c;
    }
    if (c > FastAbsF(r)) {
        c = FastAbsF(r);
    } else if (c < -FastAbsF(r)) {
        c = -FastAbsF(r);
    }
    return FastAddRots(a, c);
}
